// BCD-to-binary conversion: one-hot binary => decimal.
function [3:0] bcd2dec;
    input [3:0] bcd;
    begin
        case (bcd)
            4'b0000: bcd2dec = 4'd0;
            4'b0001: bcd2dec = 4'd1;
            4'b0010: bcd2dec = 4'd2;
            4'b0011: bcd2dec = 4'd3;
            4'b0100: bcd2dec = 4'd4;
            4'b0101: bcd2dec = 4'd5;
            4'b0110: bcd2dec = 4'd6;
            4'b0111: bcd2dec = 4'd7;
            4'b1000: bcd2dec = 4'd8;
            4'b1001: bcd2dec = 4'd9;
            default: bcd2dec = 4'd0;
        endcase
    end
endfunction

// Binary-to-BCD conversion: decimal => one-hot binary.
function [3:0] dec2bcd;
    input [3:0] dec;
    begin
        case (dec)
            4'd0:   dec2bcd = 4'b0000;
            4'd1:   dec2bcd = 4'b0001;
            4'd2:   dec2bcd = 4'b0010;
            4'd3:   dec2bcd = 4'b0011;
            4'd4:   dec2bcd = 4'b0100;
            4'd5:   dec2bcd = 4'b0101;
            4'd6:   dec2bcd = 4'b0110;
            4'd7:   dec2bcd = 4'b0111;
            4'd8:   dec2bcd = 4'b1000;
            4'd9:   dec2bcd = 4'b1001;
            default: dec2bcd = 4'b0000;
        endcase
    end
endfunction

