module TopModule(input clk, input reset, input ena, output reg pm, output reg [7:0] hh, output reg [7:0] mm, output reg [7:0] ss);
  reg [3:0] s_100;
  reg [3:0] s;
  reg [3:0] m_10;
  reg [3:0] m_1;
  reg [3:0] h_10;
  reg [3:0] h_1;
  always @(posedge clk) begin
    if (reset) begin
      s_100 <= 4'd0;
      s <= 4'd0;
      m_10 <= 4'd0;
      m_1 <= 4'd0;
      h_10 <= 4'd1;
      h_1 <= 4'd2;
      pm <= 1'b0;
    end else if (ena) begin
      s_100 <= s_100 + 4'd1;
      if (s_100 == 4'd10) begin
        s_100 <= 4'd0;
        s <= s + 4'd1;
        if (s == 4'd60) begin
          s <= 4'd0;
          m_10 <= m_10 + 4'd1;
          if (m_10 == 4'd6) begin
            m_10 <= 4'd0;
            m_1 <= m_1 + 4'd1;
            if (m_1 == 4'd10) begin
              m_1 <= 4'd0;
              h_10 <= h_10 + 4'd1;
              if (h_10 == 4'd1 && h_1 == 4'd12) begin
                h_10 <= 4'd1;
                h_1 <= 4'd1;
                pm <= ~pm;
              end else if (h_10 == 4'd2 && h_1 == 4'd12) begin
                h_10 <= 4'd1;
                h_1 <= 4'd2;
              end else if (h_1 == 4'd12) begin
                h_10 <= 4'd1;
                h_1 <= 4'd1;
              end else begin
                h_1 <= h_1 + 4'd1;
              end
            end
          end
        end
      end
    end
  end
  assign hh = {h_10, h_1} + 8'd16 * pm;
  assign mm = {m_10, m_1};
  assign ss = {s_100, s};
endmodule

