// independent of the clock frequency).
reg pulse;
always @(posedge clk) begin
    if (reset) pulse <= 0;
    else if (ena && ($time % 12 == 0)) pulse <= 1;
    else pulse <= 0;
end

// The actual 12-hour clock, incremented once per second by the
// independent pulse.
reg [3:0] hh;
reg [3:0] mm;
reg [3:0] ss;
reg pm;
