    if (reset) begin
        hh <= 4'd1;
        mm <= 4'd2;
        ss <= 4'd3;
        pm <= 1'b0;
    end else if (pulse) begin
        ss <= ss + 1;
        if (ss == 4'd10) begin
            ss <= 4'd0;
            mm <= mm + 1;
            if (mm == 4'd60) begin
                mm <= 4'd0;
                hh <= hh + 1;
                if (hh == 4'd13) begin
                    hh <= 4'd1;
                    pm <= ~pm;
                end
            end
        end
    end
end

// BCD-ify the hours, minutes, and seconds.
reg [7:0] hh_bcd;
reg [7:0] mm_bcd;
